// One-off generator: mirrors bm25.mjs (pure JS, zero Node APIs) into
// shared/bm25.js, a plain non-module <script> the browser tools load
// directly — same pattern as gen-editorial-intelligence-browser.mjs.
// Re-run this any time bm25.mjs changes; do not hand-edit the generated file.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, '..', '..', '..');
const src = fs.readFileSync(path.join(__dirname, 'bm25.mjs'), 'utf8');

// Strip `export ` keywords (the only ESM-specific syntax this file uses) —
// everything else is plain JS, safe to run as-is in a non-module <script>.
const body = src.replace(/^export /gm, '');

const out = `// AUTO-GENERATED by gen-bm25-browser.mjs from Automation/core/src/bm25.mjs.
// Do not hand-edit — re-run the generator instead so this never drifts from
// the canonical source. Exposes window.BM25 = { tokenize, scoreAndRank }.
(function(global){
${body}
global.BM25 = { tokenize, scoreAndRank };
})(typeof window !== 'undefined' ? window : this);
`;

const outDir = path.join(REPO_ROOT, 'shared');
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(path.join(outDir, 'bm25.js'), out);
console.log('wrote shared/bm25.js');
